mapper.select:
SELECT FROM outside_work_requests r JOIN users u ON u.id = r.user_id LEFT JOIN teams t ON t.id = u.team_id WHERE (#{userId} IS NULL OR r.user_id = #{userId})
AND r.user_id IN #{uid}
AND (#{from} IS NULL OR r.work_date >= #{from}) AND (#{to} IS NULL OR r.work_date <= #{to}) ORDER BY r.work_date DESC, r.id DESC

mapper.update:
UPDATE outside_work_requests
SET status = #{status}, decided_by = #{decidedBy}, rejected_reason = #{rejectedReason}
WHERE id = #{id}
